# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_agent() {
    _helper_herdr_query 'if type=="array" then .[] elif has("agents") then .agents[] else empty end | (.label // .name // .id // empty) | tostring' herdr agent list
}

_choice_command() {
    _argc_util_comp_command
}

_choice_git_ref() {
    git for-each-ref --format='%(refname:short)' 2>/dev/null
}

_choice_machine() {
    _helper_herdr_query 'if type=="array" then .[] elif has("machines") then .machines[] else empty end | (.label // .name // .id // .ssh_target // empty) | tostring' herdr machine list --json
}

_choice_pane() {
    _helper_herdr_query 'if type=="array" then .[] elif has("panes") then .panes[] else empty end | (.id // .label // empty) | tostring' herdr pane list
}

_choice_session() {
    _helper_herdr_query '.sessions[]? | .name // empty | tostring' herdr session list --json
}

_choice_ssh_target() {
    [[ -f "$HOME/.ssh/config" ]] || return 0
    gawk 'tolower($1)=="host" { for (i=2; i<=NF; i++) print $i }' "$HOME/.ssh/config"
}

_choice_tab() {
    _helper_herdr_query 'if type=="array" then .[] elif has("tabs") then .tabs[] else empty end | (.id // .label // empty) | tostring' herdr tab list
}

_choice_workspace() {
    _helper_herdr_query 'if type=="array" then .[] elif has("workspaces") then .workspaces[] else empty end | (.id // .label // empty) | tostring' herdr workspace list
}

_helper_herdr_query() {
    local filter="$1"
    shift
    "$@" 2>/dev/null | jq -b -r "$filter" 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
